import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './CSS/Wishlist.css';

function Wishlist() {
  const [wishlistItems, setWishlistItems] = useState([]);

  // Load wishlist items from localStorage on mount & listen for updates
  useEffect(() => {
    const fetchWishlist = () => {
      const saved = JSON.parse(localStorage.getItem('wishlistItems')) || [];
      setWishlistItems(saved);
    };

    fetchWishlist();
    window.addEventListener('wishlistUpdated', fetchWishlist);
    window.addEventListener('storage', fetchWishlist);

    return () => {
      window.removeEventListener('wishlistUpdated', fetchWishlist);
      window.removeEventListener('storage', fetchWishlist);
    };
  }, []);

  // Remove single item from wishlist
  const handleRemove = (id) => {
    const updated = wishlistItems.filter(item => (item._id || item.id) !== id);
    setWishlistItems(updated);
    localStorage.setItem('wishlistItems', JSON.stringify(updated));
    window.dispatchEvent(new Event('wishlistUpdated'));
  };

  // Move item from Wishlist to Cart
  const handleAddToCart = (product) => {
    const cartItems = JSON.parse(localStorage.getItem('cartItems')) || [];
    const existingIndex = cartItems.findIndex(item => (item._id || item.id) === (product._id || product.id));

    if (existingIndex > -1) {
      cartItems[existingIndex].quantity = (cartItems[existingIndex].quantity || 1) + 1;
    } else {
      cartItems.push({ ...product, quantity: 1 });
    }

    localStorage.setItem('cartItems', JSON.stringify(cartItems));
    alert('Item added to cart successfully!');
  };

  return (
    <div className="wishlist-page-container">
      <div className="wishlist-header">
        <h1>My Wishlist ({wishlistItems.length})</h1>
        <p>Manage your saved favorite items all in one place</p>
      </div>

      {wishlistItems.length === 0 ? (
        <div className="empty-wishlist">
          <i className="fa-regular fa-heart empty-heart-icon"></i>
          <h2>Your Wishlist is Empty</h2>
          <p>Explore our products and save your favorite items to your wishlist!</p>
          <Link to="/products" className="shop-now-btn">Explore Products</Link>
        </div>
      ) : (
        <div className="wishlist-grid">
          {wishlistItems.map((product) => {
            const productId = product._id || product.id;
            return (
              <div key={productId} className="wishlist-card">
                <button 
                  className="remove-wishlist-btn" 
                  onClick={() => handleRemove(productId)}
                  title="Remove from Wishlist"
                >
                  <i className="fa-solid fa-xmark"></i>
                </button>

                <div className="wishlist-img-box">
                  <img src={product.image || product.images?.[0]} alt={product.title || product.name} />
                </div>

                <div className="wishlist-info">
                  <h3>{product.title || product.name}</h3>
                  <div className="wishlist-price-box">
                    <span className="wishlist-current-price">{product.price}</span>
                    {product.originalPrice && (
                      <span className="wishlist-original-price">{product.originalPrice}</span>
                    )}
                  </div>
                  <div className="wishlist-actions">
                    <button 
                      className="move-to-cart-btn"
                      onClick={() => handleAddToCart(product)}
                    >
                      Add to Cart
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

export default Wishlist;
